{
    /// <summary>The options page's groups in its order, as the settings list's sidebar names them.</summary>
    public static readonly string[] SettingGroups = { "Start here", "Your character and home", "The city", "Getting around", "Work", "Money", "Your businesses", "Controls", "Performance", "Troubleshooting" };

    /// <summary>Each section: its group, its title, then its options as a kind (S switch, R slider, C choice), its name and its sentence, the main switch first.</summary>
    public static readonly string[][] SettingSections =
    {
        new[] { "0", "The Guide" },
        new[] { "0", "Presets" },
        new[] { "0", "Your choices" },
        new[] { "0", "Something wrong?" },
        new[] { "1", "Needs and wellbeing", "SM", "Home life and health", "Needs, routines at home, sleep, illness and fitness. Off, none of it runs.", "S", "Hygiene, stress and a tidy home", "Hygiene, stress and the state of your home wear down and have to be looked after.", "S", "Bars for hygiene, stress and home", "Three more bars show under the game's own all the time, and the home bar waits until you have a home.", "S", "Easy needs", "Needs wear down half as fast and illness is half as likely.", "S", "Sleep quality and sleep debt", "How well you slept counts, and sleep you miss has to be caught up.", "S", "Morning summary after a night's sleep", "After a night's sleep a short summary says how you are.", "S", "The night's news in the morning summary", "The weather, city policies, works next door, street events and papers that came while you slept come with the morning summary, in one or two notifications. Off: each comes alone.", "S", "Illness and the doctor", "You can catch a cold or the flu, get food poisoning, back pain or burnout, and see the doctor at the hospital." },
        new[] { "1", "Home routines and fitness", "S", "Cooking, coffee, tidying and floor exercises", "At home you can cook, make coffee, tidy up and exercise on the floor.", "S", "Fitness and diet", "Exercise and what you eat make you fitter or less fit.", "S", "Your body changes with exercise and food", "Your character's build changes slowly with exercise and food, when you wake up.", "S", "Going for a run", "You can go for a run from home." },
        new[] { "1", "Meals and music" },
        new[] { "1", "Looks and hair", "S", "The mod's clothes, shoes and fuller scalp", "The mod's clothes and shoes can be worn, and hair no longer looks thin from a distance.", "S", "Detailed player character in the city", "Your character uses the game's detailed model in the city. This changes the picture.", "S", "Fuller hair and beards", "Hair and beards on detailed characters are thicker. This changes the picture.", "S", "Finer skin up close", "A fine grain and a calmer shine on your character's skin when the camera is close.", "S", "Softer light in character creation and shops", "Faces are lit more softly in character creation and in shop previews." },
        new[] { "1", "Clothes (men)" },
        new[] { "1", "Clothes (women)" },
        new[] { "1", "Clothes shops", "S", "Clothes rack in clothing stores", "Clothing stores have a rack to buy from, and your wardrobe holds the mod's clothes.", "S", "Clothes must be bought", "You can only wear the mod's clothes you have bought. This is kept for each save." },
        new[] { "1", "Roommates" },
        new[] { "1", "Household staff" },
        new[] { "1", "Power, water and internet", "S", "Internet speed matters", "Tech firms work faster on a faster office connection, and an online shop takes as many orders a day as its building's connection allows. Off: only having a connection counts, as before." },
        new[] { "1", "Family", "SM", "A partner, a wedding, children, relatives", "A partner can move in, and an engagement, a wedding, children and relatives follow.", "S", "Your partner appears at home", "Your partner is seen at home as a character. Off, they still live with you, in notices and conversations.", "S", "Engagement and wedding", "Rings, the proposal, the planning and the day itself.", "S", "Children", "You can decide together to have a child, by pregnancy or adoption, and watch them grow up.", "S", "Relatives visit and invite you", "Mom and the in-laws react to your news, drop by and invite you to holiday dinners.", "S", "Arguments, time apart and divorce", "Chores, arguments, time apart and divorce can happen. Off, none of them ever do.", "C", "Who 'Someone special' introduces you to", "Whether the people 'Someone special' introduces are women, men or either.", "R", "Weeks per year of a child's age", "How many in-game weeks pass for a child to be a year older." },
        new[] { "1", "Your partner and your fortune", "S", "Partner cuts back at work as you prosper", "Once you are well off, a partner who lives with you may ask to work half days. Off, they always work full days.", "S", "Partner reacts to your wealth", "As your income and cash grow, your partner reacts by how they are: proud, or a little envious. Off, it is never mentioned.", "S", "Partner expects more as you prosper", "As your income and cash grow, your partner expects a bigger home, evenings out, an allowance, a car and a second home. Off, nothing is expected." },
        new[] { "1", "Friends and social life", "SM", "Family, friends and a partner", "You have family, friends and perhaps a partner, each with a contact on the phone.", "S", "New people come up to you", "Somebody new comes up to you after the gym, a shift, a coffee or a good turn.", "S", "Relationships fade if neglected", "People drift away if you neglect them, and a relationship can be damaged. Off, nothing is ever lost.", "S", "Outings with people", "You can make plans with people and keep them: coffee, a meal, the cinema, a walk, a drive.", "S", "People get in touch themselves", "People invite you, ask favours, bring news and visit your shop.", "S", "Text messages from people", "People send you text messages.", "R", "Most texts in a day", "The most texts you get in one day, from everybody together.", "S", "Type your own words in calls", "With an RLO Texts pack, you type your own reply on a call and they answer in their own words. Off: you pick one of two replies." },
        new[] { "1", "Networking", "S", "People with positions", "Some people you meet hold a position, such as a recruiter or an investor, and do you a favour or two as you grow closer. Off: nobody does." },
        new[] { "1", "Street talk" },
        new[] { "1", "Flare social media", "SM", "Flare, the city's social media app", "A phone app where you post what you really did and the city answers.", "S", "Flare notifications", "Flare's few notifications, one a day at most. Off: none at all; the app's badge still counts.", "C", "How busy the feed is", "How many posts the city's people, accounts and businesses make each day.", "S", "The City Office acts on reports", "Reports on Flare bring crews, patrols, cleaning and inspections. Off: the City Office only answers, and complaints never reach the paper.", "S", "Share your posts in Going Public", "In a Going Public session your posts go to the shared feed. Off: they stay on your own phone, except reports, which always go to the City Office.", "S", "Share your pictures in Going Public", "Pictures go with your posts as small copies, four a day at most. Off: your posts go without them.", "C", "Filter for other players' words", "Standard uses Steam's own filter, or the mod's word list without it. Strict uses both and hides web addresses.", "C", "Flare's look", "Light, dark, or dark from seven in the evening to seven in the morning. The 'Dark' or 'Light' button on Flare's top bar changes it too.", "S", "Pictures beside every account", "Faces drawn by the game's own portrait camera, the game's logos for businesses, emblems for the city's offices. Off: the initials, as before.", "C", "Photos in the city's posts", "How many of the city's posts carry a photo. Flare photographs the streets, fronts and parks you pass; a post shows one that fits its place, hour and weather." },
        new[] { "1", "Flare in the city" },
        new[] { "1", "RLO Texts" },
        new[] { "1", "Your own AI" },
        new[] { "1", "Standing and reputation", "SM", "Standing: the city reacts to your success", "Your wealth, how well the city knows you and what it thinks of you, with what moves each. The Finance app's Overview opens it.", "S", "Passers-by and customers recognise you", "Now and then somebody in the street, a customer or your staff take notice of you. One notice a day at most.", "S", "Reporters, the night show and magazines", "A reporter in the street, invitations to the night show and to a magazine, and pieces in the City Ledger about what you do.", "S", "Officials who offer favours for a bribe", "An official may offer to make an inspection a formality for cash. A bribe can come out later as an investigation.", "S", "A notification when the city asks something of you", "A notification when the city asks you for money, such as a street party or a gift to charity. Off: the requests still come to the Standing page in the Finance app." },
        new[] { "1", "The City Ledger", "SM", "The City Ledger morning paper", "The city's morning paper as a newspaper: delivered to your door, bought at a kiosk near your home, or read on your phone. Off: no paper, and nothing is charged.", "S", "Newspaper kiosks near your home", "Kiosks on the pavement near your home sell the paper by day. Off: it only comes to the doors of subscribers.", "S", "Online papers on your phone (Newsstand)", "The City Ledger and three other papers read on your phone by subscription, over your home's internet. Off: no online editions, and nothing is charged for them.", "S", "A notification when the morning's papers come", "One notification each morning naming the papers that came to your phone. Off: they come all the same, without a word.", "S", "Company milestones and rivals in the City Ledger", "Stories when you take over a rival tycoon, when a company's market value passes a round figure, and when the city's most valuable company changes. Off: none of these." },
        new[] { "1", "Leisure", "SM", "Things to do for fun", "Chess, fishing, nights out, sightseeing and photo mode. Off, none of them can be started.", "S", "Street chess", "A chess player sits on the pavement by day, and you can play.", "S", "Fishing at the waterfront", "You can fish at the water's edge.", "S", "Dancing and drinks in nightclubs", "Nightclubs have a dance floor and a bar. Driving after drinks is an offence.", "S", "Sightseeing at landmarks", "Landmarks can be taken in and ticked off.", "S", "Cinemas and theatres say what is showing", "Cinemas and theatres name the film or play that is on.", "S", "People outside clubs and cinemas at night", "Two people stand outside an open club, cinema or theatre at night.", "S", "Photo mode", "The photo mode key stops the game for a picture." },
        new[] { "1", "Life events", "SM", "Random life events", "Now and then something happens to you: a windfall, a cold, a call from Mom.", "R", "Life events per week", "About how many life events come in a week." },
        new[] { "1", "Permadeath" },
        new[] { "1", "Your phone", "S", "The mod's phone contacts", "The phone gets the mod's contacts: 911, the doctor, a friend, Mom and the rest. This applies the next time a save is loaded.", "S", "Groups in the Contacts app", "The Contacts app gets a button for each group of the mod's contacts, beside the game's own. Off, the mod's contacts are all under General.", "S", "Modern phone look", "The phone gets a modern body, wallpaper and status bar.", "S", "App folders on the phone", "The mod's apps stand in five folders on the home screen, with a dock for two favourites. Right click an app to move it. Off, every app has its own tile.", "S", "The mod's notifications carry their own picture and colour", "Each notification from the mod shows a picture of its kind on an indigo disc, where it pops up and in the notification list. Off: they look like the game's." },
        new[] { "1", "Camera and Gallery" },
        new[] { "2", "Street life", "SM", "People working and out on the pavements", "People work and go about their day on the pavements. There are never more than 8 at once.", "R", "How much is going on (1 to 10)", "1 is now and then, 10 is always something.", "S", "People at work", "Sweepers, road crews, window cleaners, couriers, painters and gardeners are at work.", "S", "Everyday people", "Friends talk, people smoke, phone, jog, queue and put up umbrellas in the rain.", "S", "Coffee from the coffee cart", "You can buy a coffee at the coffee cart with the interact key." },
        new[] { "2", "New buildings" },
        new[] { "2", "Uptown and Cedar Heights" },
        new[] { "2", "Uptown's landmarks" },
        new[] { "2", "Birchwood School" },
        new[] { "2", "Events and weather", "S", "Fires and the fire service", "Cars, bins and shopfronts catch fire now and then, and the fire service comes.", "R", "How often fires break out (1 to 10)", "1 is rare, 10 is one every eight minutes or so.", "S", "Weather affects driving, crime and energy", "Wet roads, mist, storms, heat waves and cold snaps change driving, traffic, accidents, crime and your energy.", "R", "Heat waves and cold snaps (1 to 10)", "1 is hardly ever, 10 is nearly half the days of summer and winter.", "S", "Street events", "Markets, parades, protests, fun runs, film shoots and fireworks close a street, announced the day before.", "R", "Days with a street event (1 to 10)", "1 is one day in twelve, 10 is four days in five. The Saturday market and fireworks nights are fixed.", "S", "Notifications about protests", "Notifications that a demonstration is planned, has begun or is over. Off: protests still happen and close their street, and the City Bulletin still lists them." },
        new[] { "2", "Seasons and snow" },
        new[] { "2", "Accidents and emergency services", "S", "Traffic accidents and emergency services", "Other cars crash now and then, and police and ambulances come.", "R", "How often accidents happen (1 to 10)", "1 is rare, 10 is often. At 2, the default, about one accident near you every 32 game hours in the street, fewer at night, more in bad weather.", "S", "Notifications about accidents", "The messages and their sound as an accident near you unfolds. Off: the accidents still happen, silently; what you do yourself, such as helping, is still told.", "S", "A waypoint to each accident", "The orange marker that shows where an accident is and how far, and the route to it. Off: no marker; the accident is still there to come across.", "S", "Sirens on emergency vehicles", "Police cars, ambulances and fire engines sound their sirens on the way.", "S", "People at accidents and on the street", "Drivers get out after a crash, paramedics work, and officers stand at scenes.", "S", "Your crashes cost money and can injure you", "Crashing your car costs damages and can hurt you.", "S", "People you hit fall and can be hurt", "A person your car hits is thrown down and can be hurt or killed. Off, cars pass through people.", "S", "Traffic can knock you down on foot", "A car that hits you on foot throws you down.", "S", "Traffic can hit pedestrians near you", "Now and then a pedestrian near you is hit by a car, and help comes." },
        new[] { "2", "Police", "SM", "Police", "Patrol cars come to accidents and crimes, officers walk the streets, and drivers are pulled over.", "R", "Police on the streets (0 to 10)", "How many parked patrol cars and officers you see about. 0 is none.", "S", "Officers on foot patrol near you", "Police officers on foot pass near you from time to time.", "R", "How often officers patrol (1 to 10)", "1 is rare, 10 is often.", "S", "Police chase you after a hit-and-run", "If you hit a car or a person and drive off, the police come after you.", "S", "Police stop you for traffic offences", "Red lights, speeding and reckless driving get you stopped, and jaywalking gets a warning or a fine." },
        new[] { "2", "Police stations and arrests", "SM", "Police stations in every district", "Each district has a police station with its sign, patrol cars and officers at the door.", "S", "Police stations you can walk into", "You can go in to the front desk, the waiting area and the holding cell. Off, the front desk answers at the door.", "S", "Furnished police stations", "Desks, lockers, a briefing room, a break room and the game's walls and floors, officers at work, and back offices on a large station's bare floor. Off, it is bare as before.", "S", "Police stations on the city map", "Police stations have markers, names and their own filter on the city map.", "S", "Arrests end in a holding cell", "After an arrest you sit in a holding cell at the nearest police station. Off, time passes where you were caught." },
        new[] { "2", "Crime", "SM", "Crime near you", "Street crime, thieves in shops and drivers pulled over happen near you.", "R", "How often crime happens (1 to 10)", "1 is rare, 10 is often." },
        new[] { "2", "Courts and prison" },
        new[] { "2", "City faults" },
        new[] { "2", "The council", "SM", "City government and public works", "The city has a government and a programme of public works, with City Hall on the phone.", "S", "Elections and the mayor", "Campaigns run in the street, you can vote, and policies change the city. Off, every policy effect is taken back.", "S", "Standing for office", "You can stand for the council or for mayor and govern if you win. Off, nothing new begins; papers already filed stay on the ballot.", "S", "Construction sites", "Roadworks, scaffolding, shop refits and utility works appear and progress over days." },
        new[] { "2", "City sounds", "SM", "City sounds", "Birds, crickets, distant traffic and the murmur of crowds are heard in the city.", "R", "Birds by day (volume %)", "How loud the birds are.", "R", "Crickets at night (volume %)", "How loud the crickets are.", "R", "Distant traffic (volume %)", "How loud the far-off traffic is.", "R", "Crowd murmur (volume %)", "How loud the murmur near people is." },
        new[] { "3", "Camera", "SM", "Third-person camera", "The camera follows behind your character. Off, the game's own camera is used.", "S", "Third-person camera indoors too", "The third-person camera is used inside buildings as well.", "R", "Camera tilt (degrees)", "How steeply the camera looks down. With mouse look on, this is the tilt it starts at.", "R", "Camera distance", "How far behind your character the camera stands.", "R", "Field of view (degrees)", "How wide the view is. A higher number shows more and makes things smaller.", "R", "Camera aim height (tenths of a metre)", "The height on your character that the camera looks at.", "R", "Camera swings behind you (0 is never)", "With mouse look off, how quickly the camera comes round behind you.", "S", "Chase camera when driving", "A camera that follows behind your car. Hold the look-behind key to look back.", "R", "Chase camera distance", "How far behind your car the chase camera stands." },
        new[] { "3", "Car performance", "SM", "Realistic car performance", "Every car accelerates and tops out like its kind. Off, the game's own cars.", "R", "Top speed (% of each car's own)", "The top speed of every car, as a share of what its kind really reaches.", "R", "Acceleration (% of each car's own)", "How quickly every car gains speed, as a share of what its kind really does." },
        new[] { "3", "At the wheel", "S", "Smooth throttle", "The key eases the pedal down, so a tap pulls away gently.", "S", "Speedometer when driving", "Your speed is shown on screen while you drive.", "S", "Radio station and song on screen", "The radio station and the song are named on screen while you drive." },
        new[] { "3", "Car handling", "C", "Car handling", "The car you drive keeps the game's grip, steering and springs, with a little more weight and roll, and settles after bumps. Light is almost the game's own, Heavy adds more." },
        new[] { "3", "Owning a car", "SM", "Car servicing, wear, breakdowns and insurance", "Your cars need servicing and insurance, wear out and can break down.", "S", "Easy car ownership", "Your cars use no fuel, never break down and do not wear." },
        new[] { "3", "Custom shop", "SM", "Custom shop at repair garages", "Drive a car of yours into a repair bay to paint it and fit parts.", "S", "Paint, tints and fitted parts show", "Paint, lamp tints, underglow and fitted parts are seen on your cars.", "S", "Performance parts take effect", "Fitted performance parts change how the car drives.", "S", "Underglow lights up after dark", "Underglow kits light the road under the car after dark.", "S", "Fines for loud exhausts and no helmet", "A straight-through exhaust, or riding without a helmet, can be fined.", "S", "Recorded car sounds", "The car you drive plays a real recorded engine of its kind, with the custom shop's exhausts and turbos, pops when you lift off and tyre squeal. Off: the game's own sounds.", "S", "Custom shop work counts when a car is sold", "A car sold with custom shop work on it fetches part of what the work cost on top of the game's price, less when worn. Off: the game's price only." },
        new[] { "3", "Bicycles and motorbikes", "S", "Bicycles and motorbikes", "Bicycles and motorbikes can be hired, bought and ridden." },
        new[] { "3", "Traffic and pedestrians", "S", "People react to your horn", "People in your way hurry or stop and glare when you sound the horn, and others look round.", "S", "Reckless drivers cause the accidents", "Accidents come from speeders, red-light runners and drunk drivers you can watch go wrong. Off, they are set up out of view.", "S", "Traffic brakes for people in the road", "Cars brake for people in the road, sound the horn and wait. Off, cars drive through people.", "S", "Traffic brakes in good time and leaves you room", "Cars near you slow early and smoothly, keep room behind you while you park and let you out of a space. Off, cars drive as they do in the game.", "S", "A tow truck takes the wrecks away", "Once an accident has cleared, a tow truck comes for a car too damaged to drive and loads it on its bed. Off: the wreck is simply gone, as before." },
        new[] { "3", "Buses and subway", "S", "Bus stops and buses", "Buses run between bus stops, and you can ride for a flat fare.", "S", "People waiting at bus stops", "People wait at bus stops and get on and off.", "S", "Subway journeys take time", "A ride on the game's subway takes the time of a real journey: the wait for a train, the stops and any delays." },
        new[] { "3", "Taxi", "S", "Taxi by phone", "You can call a taxi to where you stand from the phone." },
        new[] { "3", "Minimap and GPS", "SM", "Minimap", "A small map of the streets round you is shown on screen.", "S", "Minimap turns with the camera", "The minimap turns with the camera, so that what is ahead on the screen is up. Off, north is up.", "R", "Minimap size (%)", "How large the minimap is on screen.", "R", "Minimap zoom (%)", "How close the minimap looks. A higher number is closer.", "S", "Buildings and water on the minimap", "The minimap shows buildings and water. Off, roads only.", "S", "Use the other mod's route line", "The route line of the other mod is used. Off, this mod's route, on the minimap only." },
        new[] { "3", "District view" },
        new[] { "3", "Licences and the driving school", "SM", "Driving needs a licence", "You need a licence for what you drive. Off, anyone may drive anything, as in the game itself.", "S", "New saves start with a licence", "A new save that owns no vehicle starts with a driving licence.", "S", "Driving school, lessons and tests", "Driving schools have desks for the theory test, lessons and the driven test.", "S", "Penalty points on your licence", "Booked offences put points on your licence, and twelve suspend it.", "S", "Roadside licence checks", "Now and then a patrol car pulls you over to see your licence.", "S", "Heavy trucks need a heavy goods licence", "The Freight Truck, the game's largest vehicle, needs a heavy goods licence on top of the commercial one, and it opens better paid heavy loads. Off: the commercial licence covers it." },
        new[] { "3", "Travel and hotels", "S", "Hotels to stay in", "Eight hotels take guests, booked at the door.", "S", "Holidays, and burnout without a break", "Travel agencies sell holidays, and going too long without a break wears you out.", "S", "Suitcase, insurance, a companion, trade fairs", "A suitcase, travel insurance, a companion and trade fairs can be added to a trip." },
        new[] { "4", "Jobs and gigs", "SM", "Jobs from the Gig Line", "You can take jobs yourself by calling the Gig Line on your phone.", "R", "Job pay (%)", "What the jobs pay, as a share of normal.", "S", "Ride fares: easier passengers", "Passengers mind hard stops, bumps and speeding less: a jolt costs half and counts once every 6 seconds. Crashes, police stops, tips and the fare are as before.", "S", "Drinks cart sounds", "At the drinks cart you hear a customer reach the counter, again if their order nears its end untouched, and the till when they pay. Off, the cart is silent." },
        new[] { "4", "Careers", "S", "Careers with employers", "The help-wanted boards lead to employers with a rota, reviews and promotions." },
        new[] { "4", "Building trades" },
        new[] { "4", "Courses and skills", "SM", "Courses at the school and your own skills", "Short courses and diplomas at the school, on a timetable with homework and an exam, teach skills of your own that jobs ask for.", "S", "A notice when your class starts elsewhere", "A notification when one of your classes starts and you are not inside the school or university that holds it, once a class. Off: the older notice instead." },
        new[] { "4", "University and degrees", "S", "Degrees, certificates and student loans", "Degrees at Hudson City University and on the wards, certificates studied at home, grants, a student loan and graduation day." },
        new[] { "4", "Family, tutoring and academies", "S", "University for your children, tutoring and an academy", "A grown child goes to university with the college fund, you can tutor from home, and you can open a training academy of your own." },
        new[] { "4", "Professional jobs", "S", "Professional jobs at the city's employers", "Work as anything you are qualified for: the city's businesses, your rivals', its tech companies and the public sector take you on by your qualifications and skills.", "S", "Recruitment office reminder", "A notification on the last day of your registration with the recruitment office. Off: the registration ends all the same, without a word.", "S", "The reason for a rejection", "When an employer turns down your application, the notification says how many points you were short of the score they wanted, or that it was close. Off: the no alone." },
        new[] { "4", "Working life", "S", "Reviews, promotions and working life", "A job brings reviews, rises, bonuses and promotions, office matters, overtime and burnout, search firms, redundancy, options, a pension and the top seats." },
        new[] { "4", "Management ladder", "S", "The management ladder at the city's companies", "A job at a city chain's store climbs from the floor to store manager, regional manager and executive, each rank with its own tools. Off: the profession's ranks alone." },
        new[] { "4", "Working for yourself", "S", "Freelance work, practices and founding your own", "Leave a profession to found a company or open a practice, take colleagues along, mind a restraint clause, and take freelance contracts from clients.", "S", "A notification for each contract offered", "A notification when a client offers you a freelance contract. Off: the offers still come, on the Own work tab of the Career app." },
        new[] { "4", "The Planner", "SM", "Planner on the phone", "An app on the phone lists everything you have to do.", "S", "Planner reminders", "The Planner reminds you of what is coming up.", "S", "The morning line", "On waking, one notification of your day: how many entries, the first and when to leave for it. Nothing on an empty day." },
        new[] { "4", "The Calendar" },
        new[] { "4", "The Marketplace" },
        new[] { "5", "Credit rating and loans", "S", "Credit rating and phone loans", "You have a credit rating, banks lend by it, and loans can be taken from the phone. Off, the banks' own terms and no Finance app.", "S", "A notification when your credit rating rises", "A notification when your credit rating moves up a grade. Off: only a fall is told, and the Finance app shows your rating either way.", "S", "Day-end result includes the mod's money", "The day-end panel and the top bar show your profit or loss with the mod's money too, less loan payouts and share trades. Off: the game's own figure." },
        new[] { "5", "Debt", "S", "Overdraft, cards, mortgage and other credit", "Adds an overdraft, a credit card, a business loan, car finance, a mortgage and consolidation. Off, nothing new is opened and what you owe stays owed.", "S", "The private lender", "A private lender lends when no bank will. Off, it lends nothing, and a debt to it can still be paid.", "S", "Consequences of not paying", "Missed payments bring fees, a penalty rate, collections, repossession and a court claim. Off, only your rating suffers.", "C", "How hard not paying hits", "Relaxed is forgiving, Hardcore is strict. The presets set this." },
        new[] { "5", "Banks app", "S", "Banks app", "One Banks app on the phone for the city's banks, with your accounts, loans and card at each. Off, no Banks app shows and the Finance app still has everything." },
        new[] { "5", "The city's economy", "SM", "The city's economy", "The city has a bank rate, prices and good and bad years that reach your customers. Off, the game's own rates, prices and customers.", "C", "How far the economy swings", "Relaxed keeps the economy calm, Hardcore lets it swing wide. The presets set this.", "S", "The rate decision ahead", "The evening before a decision of the central bank takes effect, one notification of what the market expects. Off: the decision comes without it." },
        new[] { "5", "The Economy app" },
        new[] { "5", "Investors", "S", "Investors", "Investors make offers for a share of your businesses and meet you. Off, no new offers, and deals you have carry on.", "C", "How demanding investors are", "Relaxed investors are patient, Hardcore ones want growth quickly. The presets set this." },
        new[] { "5", "The stock market", "SM", "The city's stock market", "The city's stock market and the Stocks app. Off, the market stands still and nothing is traded; the shares you hold are kept.", "S", "Margin trading", "A margin account can borrow against your shares and sell short, with margin calls. Off, no new account is opened and one that is open can only be wound down.", "S", "Listing your own company", "Your businesses can come to the market as a company with shareholders. Off, no new listing begins; a company already listed stays until it is taken private.", "S", "Trading bots", "Trading bots you can hire in the Stocks app to trade your own cash. Off, none is hired and every bot hired is let go, its shares yours.", "S", "A notification when a dividend is paid to you", "A notification with the amount when a dividend is paid to you or your bots, one for several at once. Off: they are still paid and listed in the market news.", "S", "Bonds and deposits", "Bonds and bank deposits on the Stocks app's Bonds tab, paying interest on a schedule. Off, none is bought or rolled over; those you hold still pay, end and can be sold.", "S", "A bond's interest so far", "Each notice of a bond's interest adds what that bond has paid you so far, after tax. Off: the payment alone.", "S", "Futures and options", "Raw material prices that move at each market close, with futures and options on the Stocks app's Futures tab. Off, prices are as before; what you hold runs to its day." },
        new[] { "5", "Large investors", "C", "The most of a company you may hold", "How much of one listed company you may own; 10% is the old rule. Lowered, a holding already past it is kept: only new buying is refused.", "S", "Worked orders and larger bond purchases", "Orders over one order's most are worked over the day; their day's money is still yours for other Stocks purchases and free at the close. Bonds: bigger purchases, twice as many held.", "S", "Dividends put back into the same shares", "The share of each dividend you choose on a holding buys more of it at the next open. Off, every dividend is paid into your cash." },
        new[] { "5", "Builders and hedging", "S", "Builders on the market and hedging materials", "The city's builders on the market, moved by their tenders and sites, and building materials to hedge a project's costs with futures. Off, nothing new joins and no hedge is offered." },
        new[] { "6", "Running a business", "SM", "Running a business", "Staff, insurance, marketing, tax and licences for your businesses, with the Company app. Off, none of it runs and nothing is charged.", "S", "Staff pay, raises, strikes and sick pay", "Staff expect the going rate, ask for raises, get offers from rivals, strike, and are paid overtime and sick pay.", "S", "Business insurance", "You can take out policies, pay premiums and make claims.", "S", "Marketing campaigns", "Campaigns cost money, run for a time and end with a report.", "S", "Quarterly tax return and an accountant", "A tax return is due every quarter, and an accountant can file it.", "S", "Cash sales kept off the books", "You may keep some cash sales out of the return, at the risk of an audit. Off, nothing can be hidden.", "S", "Licences and permits", "Food hygiene, alcohol, late opening and signage need a licence or a permit.", "C", "How strict running a business is", "Relaxed is forgiving, Hardcore is strict. The presets set this." },
        new[] { "6", "Staff rota planner", "S", "Staff rota planner", "The Company app forecasts customers, advises opening hours and writes a staff rota at a press." },
        new[] { "6", "Managers", "S", "Managers for your businesses", "Managers chosen from a place's own staff make the small decisions you give them, inside your limits, on the Company app's Managers tab, and every one can be undone." },
        new[] { "6", "Company hierarchy", "S", "Company hierarchy: policy, regions and executives", "One policy all your managers obey, for the company, a region or a store. What they cannot settle goes up the ranks to you. Off, each manager keeps their own limits." },
        new[] { "6", "Cleaning service", "S", "Cleaning service", "Cleaners go round your businesses every day, and can clean for other businesses under contract." },
        new[] { "6", "Selling a business", "S", "Selling a business", "The Services app says what a business is worth, brings offers from buyers and can sell it quickly." },
        new[] { "6", "Your own bank", "S", "Your own bank", "Found a bank at your headquarters: savers, loans, a fund and a regulator, in its own app. Off, a bank you have stands still." },
        new[] { "6", "Bank branches", "S", "Bank branches", "Open branches of your bank in shop units: their customers bank with you, and busy branches bring your bank more of the city. Off, branches do nothing." },
        new[] { "6", "RLO interface", "SM", "RLO interface", "Draws Contacts and the overhaul's screens in the mod's own design: slate panels over the city, colour icons and a status bar along the bottom. Off: the game's own screens.", "C", "Interface motion", "How the RLO interface moves: full, calm (slower and shorter) or off." },
        new[] { "6", "Living population", "SM", "Living population", "The living economy overhaul, in the beta first. Off, the game and the mod run exactly as before it.", "S", "Desk sessions", "Hands-on sessions at the owner's desk in your firm's office, such as a weekly team meeting, or a manager who holds them for you." },
        new[] { "6", "Game studio", "S", "Game studio", "Games made from a concept to their life after launch: genres, platforms, milestones at your desk, hype, reviews, sales to a real audience and rival studios. Off, game studios work as before." },
        new[] { "6", "Tech firms", "S", "Tech firms rebuilt", "Software, AI, consultancy, security, web, design and data centres sell into markets sized from the city, against rivals by the same rules, with desk sessions. Off, they work as before." },
        new[] { "6", "The end game at scale", "S", "The end game at scale", "Data centres, the cloud, your broadband company and your bank cost and earn at real size, with upkeep and crews of staff. Off, every figure is as before." },
        new[] { "6", "Brands and franchises", "S", "Brands and franchises", "Your shops can become a brand and be franchised. Off, a brand has no effect and no franchise money is paid." },
        new[] { "6", "Rival tycoons", "SM", "Rival tycoons who grow with you and fight you", "Three named fortunes with holdings on the stock market grow with you and move against you once you are rich. Off, they stand still. The Finance app's Overview opens their page.", "C", "How hard the rivals push", "Gentle pushes least, Ruthless most: how often they move and how hard. The presets set this.", "C", "When the first rival comes forward", "How rich you must be before the first tycoon comes forward, at the start's prices. 5 million is as before. The others still come at hundreds of millions and billions." },
        new[] { "6", "Online shops", "S", "Online shops", "A business or a warehouse sells its stock to the whole city through the Web shop app. Off, no orders come.", "S", "A notification for orders nobody can pick", "A notification when orders wait three opening hours with nobody on shift to pick them. Orders placed after closing wait quietly for the opening. Off: the Planner still shows it." },
        new[] { "6", "Professionals", "S", "Roles, levels and skills for professional staff", "Your programmers, designers, lawyers and HR staff get a role, a level and skills of their own, with reviews, promotions, courses and notice." },
        new[] { "6", "Jobs board", "S", "Jobs board and labour market", "Post ads for professionals in Open Roles, take on applicants from the city's job seekers and get more candidates from the recruitment office." },
        new[] { "6", "Tech sector", "S", "Software, games, IT services and security firms", "Run a software studio, game studio, IT consultancy or cybersecurity firm with products, customers and client contracts in the Tech app.", "S", "A notification for each client offer and tender", "A notification when a client offers one of your firms a contract or the council puts work out to tender. Off: they still come, on the Contracts tab of the Tech app.", "S", "A data centre question when you take a warehouse", "On taking a warehouse, a question asks whether it is to be a data centre, and Yes opens its fit-out on the Infra tab. Off: fit it out there whenever you like." },
        new[] { "6", "Startups and venture capital", "S", "Startups, venture firms and raising money", "The city's startups grow, raise, fail or are bought, and pitch you for money; your own tech firms can raise from venture firms." },
        new[] { "6", "Tech buildings", "S", "Server rooms in data centres", "Your data centres get rows of racks, cooling, power and status lights by their racks and redundancy, technicians at work, and stores and a workbench round the hall.", "S", "Tech company headquarters", "The city's tech companies each have an office building, named on the map, with their jobs there. Inside, the whole floor is their offices, with staff at work.", "S", "Data centre signs and security", "Your data centres carry your cloud's name on a sign outside, with a security booth and a barrier where there is room, and are on the map.", "S", "Tech fittings in your offices", "An office your tech firm runs in gets a server closet, a developer's desk and a whiteboard where a wall has room, never in your furniture's way." },
        new[] { "6", "Car showroom", "S", "Car showroom", "A business of its own you found in a shop unit: cars bought new, used and at auction, sold to customers, with finance and warranties. Off, it does not trade.", "S", "Visitors on the floor", "While you stand in one of your Car Showrooms, its customers walk round it looking at the cars. Off, the floor stays empty and the trade is just the same." },
        new[] { "6", "Construction company" },
        new[] { "6", "Build mode" },
        new[] { "6", "Office space", "S", "Empty shops as offices", "Some empty shops in the districts with offices become offices, so you can always choose between a few to lease. Nothing of a building is saved." },
        new[] { "6", "Property, hotels and car hire", "S", "Property to buy, let and sell", "Building values and rents move, and you can let buildings to tenants, do works and sell. Off, every value and rent is the game's own.", "S", "Owning a hotel", "A hotel you own takes guests and pays you. Off, it stands still.", "S", "Car hire business", "You can hire your cars out. Off, no car goes out, and a car that is out is called back.", "R", "Rental income (%)", "The rent your buildings earn, as a share of normal, whether you let them or the game does. Agreed leases keep their rent." },
        new[] { "6", "A landlord's duties", "S", "A landlord's duties", "Tenants have a satisfaction, report repairs and complain, and the city inspects let buildings. Lettings agencies, managers and payment plans come with it. Off, letting works as before." },
        new[] { "6", "Business events", "SM", "Business events", "Things happen to your businesses, good and bad. They are listed on the Business desk contact.", "R", "How often something comes up (1 to 10)", "1 is about one day in twelve, 10 is about one day in three. Never more than two are open at once.", "S", "Good news only", "Only bulk orders, press coverage, praise and awards come up." },
        new[] { "6", "Kinds of business event", "S", "Rival moves", "A competitor undercuts you, makes an offer to one of your staff or smears you in the paper.", "S", "Protection racket", "Someone demands protection money. You can pay, refuse, go to the police or rely on your security.", "S", "Inspections", "Health, fire safety and licence inspectors call.", "S", "Staff trouble", "A strike threat over low wages, a theft caught on camera or an argument to settle.", "S", "Supplier trouble", "A delivery comes late or a supplier adds a surcharge.", "S", "Customer complaints and praise", "A complaint or a word of praise spreads.", "S", "Tax audits", "The tax office audits a business of yours now and then.", "S", "Opportunities", "A bulk order, a piece in the paper or an award comes your way." },
        new[] { "6", "Interiors and decor" },
        new[] { "6", "District standards" },
        new[] { "6", "Decor and customers" },
        new[] { "6", "Ready-made designs" },
        new[] { "6", "New kinds of shop" },
        new[] { "7", "Keys" },
        new[] { "7", "Mouse and doors", "S", "Mouse look", "Move the mouse to look around. The 'Free the cursor' key under Controls gives the pointer back.", "R", "Mouse look sensitivity (1 to 20)", "How far the view turns for the same movement of the mouse.", "S", "Enter buildings and vehicles with the interact key", "The interact keys take you into buildings and into your vehicles without a click." },
        new[] { "7", "On foot" },
        new[] { "8", "Faster frames" },
        new[] { "8", "Shadows and detail" },
        new[] { "8", "Picture", "SM", "Picture adjustments", "The colour, contrast, bloom and detail settings below are applied. Off, the picture is the game's own.", "R", "Colour saturation (0 is the game's own)", "How strong the colours are.", "R", "Contrast (0 is the game's own)", "How far light and dark are apart.", "R", "Bloom (%), costs performance", "The glow round bright lights. At 0 it is the game's own.", "R", "Detail distance (%), costs performance above 100", "How far away the game still draws things in full detail." },
        new[] { "9", "Save tools" },
        new[] { "9", "Diagnostics" },
        new[] { "9", "Going Public (multiplayer)" },
        new[] { "9", "Measuring performance" },
        new[] { "9", "New ground (developer)" },
        new[] { "9", "Car handling tuning", "R", "Handling tuning: spring softness", "Above 100% the springs are softer and the body floats more. The car you drive takes it at once, and Player.log keeps the figures.", "R", "Handling tuning: bounce", "Above 100% the body bounces longer after a bump before it settles. The car you drive takes it at once, and Player.log keeps the figures.", "R", "Handling tuning: body roll", "Above 100% the body leans further in bends. The car you drive takes it at once, and Player.log keeps the figures.", "R", "Handling tuning: tyre grip", "Above 100% the tyres hold more before they slide. The car you drive takes it at once, and Player.log keeps the figures.", "R", "Handling tuning: steering at speed", "Above 100% the wheels turn further at speed, while the full lock at walking pace stays. Player.log keeps the figures.", "R", "Handling tuning: how quickly the brakes build", "Above 100% the brakes reach their full force sooner after you press the key. The car you drive takes it at once, and Player.log keeps the figures." },
    };
}
